import { fitField } from "../core/units.js?v=20261019c";
export const KEY = "mat072_kcc_rel3";
export const ID = 72;
export const NAME = "K&C Damage Release 3 (*MAT_CONCRETE_DAMAGE_REL3)";
export const CATEGORY = "Concrete";
